return {["fb211_01"]={["dsc"]=[[这里是通往楼内的大门。大门陈设富丽堂皇，门口挂着御赐门匾，彰显着此楼的不凡。门内是宽阔的走廊，通往楼中各处。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb211_01]],["item1"]=[[tldj2]],["item2"]=[[tldj3]],["name"]=[[大门]],["permission"]=1,["right"]=[[fb211_15]],["stepMusic"]=[[jiaobu]]},["fb211_02"]={["dsc"]=[[此处是大楼转角处建成的小角楼。顺着一人宽的木梯走上去，便来到一个木质结构的小楼上。由于不是顶楼，风景没有那般惊艳，但小楼小巧别致，倒是别有一般雅趣。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb211_02]],["item1"]=[[211dj2]],["name"]=[[角楼]],["permission"]=1,["right"]=[[fb211_03]],["rightDown"]=[[fb211_09]],["stepMusic"]=[[jiaobu]]},["fb211_03"]={["down"]=[[fb211_09]],["dsc"]=[[此处是走廊转角处的回廊。回廊是木质，其上铺有毛毯，踩上去柔软舒适。回廊的廊柱均是以浮雕装饰，颇为不凡。廊柱之下摆放有凳子，可供人休息。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb211_03]],["item1"]=[[211dj3]],["left"]=[[fb211_02]],["name"]=[[回廊]],["permission"]=1,["right"]=[[fb211_04]],["stepMusic"]=[[jiaobu]]},["fb211_04"]={["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb211_04]],["item1"]=[[211dj10]],["item2"]=[[211dj11]],["left"]=[[fb211_03]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb211_05]],["stepMusic"]=[[jiaobu]]},["fb211_05"]={["down"]=[[fb211_10]],["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb211_05]],["item1"]=[[211dj12]],["left"]=[[fb211_04]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb211_06]],["stepMusic"]=[[jiaobu]]},["fb211_06"]={["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb211_06]],["item1"]=[[211dj13]],["left"]=[[fb211_05]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb211_07]],["stepMusic"]=[[jiaobu]]},["fb211_07"]={["down"]=[[fb211_11]],["dsc"]=[[此处是走廊转角处的回廊。回廊是木质，其上铺有毛毯，踩上去柔软舒适。回廊的廊柱均是以浮雕装饰，颇为不凡。廊柱之下摆放有凳子，可供人休息。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb211_07]],["item1"]=[[211dj4]],["left"]=[[fb211_06]],["name"]=[[回廊]],["permission"]=1,["right"]=[[fb211_08]],["stepMusic"]=[[jiaobu]]},["fb211_08"]={